---
import Icon from './Icon.astro';
import type { PropItem } from '../data/component-props';
import { getMultiFrameworkSnippets, FRAMEWORK_METADATA } from '../data/multi-framework';

export interface Props {
  title: string;
  code: string;
  slug?: string;
  status?: string;
  cli?: string;
  propsDoc?: PropItem[];
}

const { title, code, slug: propSlug, status = "ASCII READY", cli, propsDoc } = Astro.props;
const derivedSlug = propSlug || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const snippets = getMultiFrameworkSnippets(derivedSlug, code);
const uniqueId = `preview-${Math.random().toString(36).substring(2, 9)}`;
const lineNumbers = (text) =>
  text.trim().split('\n').map((_, i) => String(i + 1).padStart(2, '0')).join('\n');
---

<div class="tui-window overflow-hidden" id={uniqueId}>
  <!-- Header con Tabs y Controles -->
  <div class="tui-header flex flex-wrap gap-2 justify-between items-center">
    <div class="flex items-center gap-2 min-w-0">
      <span class="bg-black text-scorch-cyan px-2 py-0.5 border border-black font-extrabold truncate max-w-full">&gt; {title}</span>
      <span class="bg-black text-slate-200 text-[10px] border border-slate-700 px-1.5 py-0.5 shrink-0">{status}</span>
    </div>

    <div class="flex flex-wrap items-center gap-2">
      {cli && (
        <button
          type="button"
          class="cli-copy-btn bg-black hover:bg-slate-800 text-slate-100 border border-slate-600 px-2 py-1 text-[11px] font-mono flex items-center gap-1.5 cursor-pointer"
          data-cli={cli}
          title="Copiar comando CLI de instalación"
        >
          <span class="text-scorch-crimson font-extrabold">$</span>
          <span class="cli-text">{cli}</span>
        </button>
      )}

      <!-- Tabs Selector -->
      <div class="flex bg-black p-0.5 border border-slate-700 text-xs">
        <button
          type="button"
          class="tab-btn active px-2.5 py-1 font-bold text-white bg-scorch-crimson border border-black cursor-pointer"
          data-tab="preview"
        >
          PREVIEW
        </button>
        <button
          type="button"
          class="tab-btn px-2.5 py-1 font-bold text-slate-200 hover:text-white cursor-pointer"
          data-tab="code"
        >
          CODE
        </button>
        {propsDoc && propsDoc.length > 0 && (
          <button
            type="button"
            class="tab-btn px-2.5 py-1 font-bold text-slate-200 hover:text-white cursor-pointer"
            data-tab="props"
          >
            PROPS
          </button>
        )}
      </div>

      <!-- Copy Button -->
      <button
        type="button"
        class="copy-btn btn-brutal bg-scorch-gold text-black text-xs px-2.5 py-1 font-extrabold flex items-center gap-1.5"
        data-code={code}
      >
        <span class="copy-icon inline-flex items-center" aria-hidden="true"><Icon name="copy" class="w-3.5 h-3.5" /></span>
        <span class="copy-text">COPIAR</span>
      </button>
    </div>
  </div>

  <!-- Vista Previa Container -->
  <div class="preview-content p-6 bg-canvas-surface dark:bg-canvas-dark-surface min-h-[120px] flex items-center justify-center">
    <div class="w-full">
      <slot />
    </div>
  </div>

  <!-- Vista Código Multi-Framework Container (Oculto por defecto) -->
  <div
    class="code-content hidden bg-[#070A0F] font-mono text-xs overflow-x-auto border-t-2 border-black dark:border-slate-800"
    data-astro-code={snippets.astro}
    data-react-code={snippets.react}
    data-html-code={snippets.html}
    data-astro-file={FRAMEWORK_METADATA.astro.getFilename(derivedSlug)}
    data-react-file={FRAMEWORK_METADATA.react.getFilename(derivedSlug)}
    data-html-file={FRAMEWORK_METADATA.html.getFilename(derivedSlug)}
  >
    <!-- Selector de Framework (Astro / React TSX / Tailwind HTML) -->
    <div class="code-framework-bar px-3 py-2 bg-slate-950 border-b border-slate-800 flex flex-wrap items-center justify-between gap-2 text-[11px] select-none">
      <div class="flex items-center gap-2">
        <span class="text-slate-500 font-bold uppercase text-[10px]">// FRAMEWORK:</span>
        <div class="inline-flex bg-black border border-slate-700 p-0.5">
          <button
            type="button"
            class="framework-tab-btn active px-2.5 py-0.5 font-bold text-white bg-scorch-crimson border border-black cursor-pointer text-[10px]"
            data-framework="astro"
          >
            ASTRO
          </button>
          <button
            type="button"
            class="framework-tab-btn px-2.5 py-0.5 font-bold text-slate-300 hover:text-white cursor-pointer text-[10px]"
            data-framework="react"
          >
            REACT (TSX)
          </button>
          <button
            type="button"
            class="framework-tab-btn px-2.5 py-0.5 font-bold text-slate-300 hover:text-white cursor-pointer text-[10px]"
            data-framework="html"
          >
            HTML / CSS
          </button>
        </div>
      </div>
      <span class="framework-filename text-[10px] text-slate-400 font-bold hidden sm:inline">
        {FRAMEWORK_METADATA.astro.getFilename(derivedSlug)}
      </span>
    </div>

    <!-- Paneles de código: numeración en un <pre> aparte para no inflar el DOM -->
    <div class="framework-pane framework-pane-astro p-4 flex gap-3">
      <pre class="select-none text-right text-slate-500 text-[11px] font-bold leading-5 shrink-0 m-0" aria-hidden="true">{lineNumbers(snippets.astro)}</pre>
      <pre class="whitespace-pre font-mono leading-5 text-slate-200 m-0 flex-1 min-w-0">{snippets.astro.trim()}</pre>
    </div>

    <div class="framework-pane framework-pane-react hidden p-4 flex gap-3">
      <pre class="select-none text-right text-slate-500 text-[11px] font-bold leading-5 shrink-0 m-0" aria-hidden="true">{lineNumbers(snippets.react)}</pre>
      <pre class="whitespace-pre font-mono leading-5 text-slate-200 m-0 flex-1 min-w-0">{snippets.react.trim()}</pre>
    </div>

    <div class="framework-pane framework-pane-html hidden p-4 flex gap-3">
      <pre class="select-none text-right text-slate-500 text-[11px] font-bold leading-5 shrink-0 m-0" aria-hidden="true">{lineNumbers(snippets.html)}</pre>
      <pre class="whitespace-pre font-mono leading-5 text-slate-200 m-0 flex-1 min-w-0">{snippets.html.trim()}</pre>
    </div>
      </div>
    </div>
  </div>

  <!-- Vista Props Container (Oculto por defecto) -->
  {propsDoc && propsDoc.length > 0 && (
    <div class="props-content hidden p-4 bg-white dark:bg-slate-950 font-mono text-xs overflow-x-auto border-t-2 border-black dark:border-slate-800">
      <div class="overflow-x-auto w-full">
        <table class="w-full border-collapse border-2 border-black dark:border-slate-700 text-left">
          <thead>
            <tr class="bg-black text-white dark:bg-slate-900 border-b-2 border-black dark:border-slate-700 text-[11px] uppercase tracking-wider">
              <th class="p-2.5 font-extrabold border-r border-slate-800 dark:border-slate-700">Prop</th>
              <th class="p-2.5 font-extrabold border-r border-slate-800 dark:border-slate-700">Tipo TypeScript</th>
              <th class="p-2.5 font-extrabold border-r border-slate-800 dark:border-slate-700">Default</th>
              <th class="p-2.5 font-extrabold border-r border-slate-800 dark:border-slate-700">Descripción</th>
              <th class="p-2.5 font-extrabold">Variantes</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-black/20 dark:divide-slate-800 text-[11px]">
            {propsDoc.map((item) => (
              <tr class="hover:bg-scorch-crimson/5 dark:hover:bg-scorch-crimson/10 transition-colors">
                <td class="p-2.5 font-extrabold text-scorch-crimson dark:text-scorch-cyan border-r border-black/10 dark:border-slate-800 whitespace-nowrap">
                  {item.name}
                </td>
                <td class="p-2.5 border-r border-black/10 dark:border-slate-800 text-sky-800 dark:text-sky-300 font-bold whitespace-nowrap">
                  <code>{item.type}</code>
                </td>
                <td class="p-2.5 border-r border-black/10 dark:border-slate-800 text-slate-600 dark:text-slate-400 whitespace-nowrap">
                  {item.default ? <code>{item.default}</code> : <span class="opacity-50">—</span>}
                </td>
                <td class="p-2.5 border-r border-black/10 dark:border-slate-800 text-slate-800 dark:text-slate-200">
                  {item.description}
                </td>
                <td class="p-2.5 text-slate-700 dark:text-slate-300">
                  {item.variants && item.variants.length > 0 ? (
                    <div class="flex flex-wrap gap-1">
                      {item.variants.map((v) => (
                        <span class="bg-slate-100 dark:bg-slate-900 px-1.5 py-0.5 border border-black/40 dark:border-slate-700 text-[10px] font-bold">
                          {v}
                        </span>
                      ))}
                    </div>
                  ) : (
                    <span class="opacity-50">—</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )}
</div>

<script>
  // Inicializar todos los ComponentPreview
  document.querySelectorAll('.tui-window').forEach((container) => {
    const tabBtns = container.querySelectorAll('.tab-btn');
    const previewContent = container.querySelector('.preview-content');
    const codeContent = container.querySelector('.code-content');
    const propsContent = container.querySelector('.props-content');
    const copyBtn = container.querySelector('.copy-btn');
    const cliCopyBtn = container.querySelector('.cli-copy-btn');

    if (!tabBtns.length || !previewContent || !codeContent) return;

    tabBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        if ((window as any).playMechanicalClick) (window as any).playMechanicalClick();
        const targetTab = btn.getAttribute('data-tab');

        tabBtns.forEach((b) => {
          b.classList.remove('active', 'bg-scorch-crimson', 'text-white', 'border', 'border-black');
          b.classList.add('text-slate-200');
        });

        btn.classList.add('active', 'bg-scorch-crimson', 'text-white', 'border', 'border-black');
        btn.classList.remove('text-slate-200');

        if (targetTab === 'preview') {
          previewContent.classList.remove('hidden');
          codeContent.classList.add('hidden');
          if (propsContent) propsContent.classList.add('hidden');
        } else if (targetTab === 'code') {
          previewContent.classList.add('hidden');
          codeContent.classList.remove('hidden');
          if (propsContent) propsContent.classList.add('hidden');
        } else if (targetTab === 'props') {
          previewContent.classList.add('hidden');
          codeContent.classList.add('hidden');
          if (propsContent) propsContent.classList.remove('hidden');
        }
      });
    });

    if (cliCopyBtn) {
      cliCopyBtn.addEventListener('click', async () => {
        const cliCmd = cliCopyBtn.getAttribute('data-cli');
        if (!cliCmd) return;
        try {
          await navigator.clipboard.writeText(cliCmd);
          if ((window as any).showToast) {
            (window as any).showToast('CLI COPIADO', `Comando listo: ${cliCmd}`, 'cyan', 2600);
          }
          const cliText = cliCopyBtn.querySelector('.cli-text');
          if (cliText) {
            const orig = cliText.textContent;
            cliText.textContent = 'COPIADO AL PORTAPAPELES';
            setTimeout(() => {
              cliText.textContent = orig;
            }, 1800);
          }
        } catch (err) {
          console.error(err);
        }
      });
    }

    if (copyBtn) {
      copyBtn.addEventListener('click', async () => {
        const textToCopy = copyBtn.getAttribute('data-code');
        if (!textToCopy) return;

        try {
          await navigator.clipboard.writeText(textToCopy);
          const currentFw = localStorage.getItem('ryukami-framework') || 'astro';
          const fwLabel = currentFw === 'react' ? 'React (TSX)' : currentFw === 'html' ? 'HTML / Tailwind' : 'Astro';
          if ((window as any).showToast) {
            (window as any).showToast('SNIPPET COPIADO', `Código ${fwLabel} copiado al portapapeles.`, 'emerald', 2800);
          } else if ((window as any).playTerminalBeep) {
            (window as any).playTerminalBeep(980, 0.08);
          }

          const copyText = copyBtn.querySelector('.copy-text');
          const copyIcon = copyBtn.querySelector('.copy-icon');

          if (copyText && copyIcon) {
            const originalText = copyText.textContent;
            copyText.textContent = 'COPIADO';
            copyBtn.classList.add('bg-emerald-400');

            setTimeout(() => {
              copyText.textContent = originalText;
              copyBtn.classList.remove('bg-emerald-400');
            }, 2000);
          }
        } catch (err) {
          console.error('Error al copiar:', err);
        }
      });
    }

    // Controlador Multi-Framework (Astro / React TSX / Tailwind HTML)
    const frameworkBtns = container.querySelectorAll('.framework-tab-btn');
    const frameworkPanes: Record<string, Element | null> = {
      astro: container.querySelector('.framework-pane-astro'),
      react: container.querySelector('.framework-pane-react'),
      html: container.querySelector('.framework-pane-html'),
    };
    const frameworkFilename = container.querySelector('.framework-filename');

    function switchFramework(fw: string) {
      frameworkBtns.forEach((btn) => {
        const isCurrent = btn.getAttribute('data-framework') === fw;
        btn.classList.toggle('active', isCurrent);
        btn.classList.toggle('bg-scorch-crimson', isCurrent);
        btn.classList.toggle('text-white', isCurrent);
        btn.classList.toggle('border', isCurrent);
        btn.classList.toggle('border-black', isCurrent);
        btn.classList.toggle('text-slate-300', !isCurrent);
      });

      Object.keys(frameworkPanes).forEach((key) => {
        const pane = frameworkPanes[key];
        if (pane) {
          pane.classList.toggle('hidden', key !== fw);
        }
      });

      if (codeContent) {
        const codeMap: Record<string, string | null> = {
          astro: codeContent.getAttribute('data-astro-code'),
          react: codeContent.getAttribute('data-react-code'),
          html: codeContent.getAttribute('data-html-code'),
        };
        const fileMap: Record<string, string | null> = {
          astro: codeContent.getAttribute('data-astro-file'),
          react: codeContent.getAttribute('data-react-file'),
          html: codeContent.getAttribute('data-html-file'),
        };
        if (copyBtn && codeMap[fw]) {
          copyBtn.setAttribute('data-code', codeMap[fw] || '');
        }
        if (frameworkFilename && fileMap[fw]) {
          frameworkFilename.textContent = fileMap[fw] || '';
        }
      }
    }

    frameworkBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const fw = btn.getAttribute('data-framework');
        if (!fw) return;
        if ((window as any).playMechanicalClick) (window as any).playMechanicalClick();
        switchFramework(fw);
        try {
          localStorage.setItem('ryukami-framework', fw);
        } catch (e) {}
        window.dispatchEvent(new CustomEvent('ryukami:framework-change', { detail: { framework: fw } }));
      });
    });

    let savedFw = 'astro';
    try {
      savedFw = localStorage.getItem('ryukami-framework') || 'astro';
    } catch (e) {}
    switchFramework(savedFw);

    window.addEventListener('ryukami:framework-change', (e: any) => {
      if (e.detail && e.detail.framework) {
        switchFramework(e.detail.framework);
      }
    });
  });
</script>

export interface PropItem {
  name: string;
  type: string;
  default?: string;
  description: string;
  variants?: string[];
}

export const buttonProps: PropItem[] = [
